Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "usermeta": {
    "deneb": {
      "build": "1.6.2.0",
      "metaVersion": 1,
      "provider": "vegaLite",
      "providerVersion": "5.16.3"
    },
    "interactivity": {
      "tooltip": true,
      "contextMenu": true,
      "selection": false,
      "highlight": false,
      "dataPointLimit": 50
    },
    "information": {
      "name": "Channel Analysis Henkel - Value & Volume v14",
      "description": "Global heatmap: color scale low->high based on Channel Metric, normalised across the ENTIRE table (both RowLabel and Channel). Grey = lowest 10%, Navy = highest 10%.",
      "author": "CF360"
    },
    "dataset": [
      {
        "key": "__0__",
        "name": "Parameter Order",
        "description": "Heatmap Parameter[Parameter Order] — 0=Brand Strategy, 1=PromoType",
        "type": "numeric",
        "kind": "column"
      },
      {
        "key": "__1__",
        "name": "Brand Strategy",
        "description": "IMS Processed[Brand Strategy]",
        "type": "text",
        "kind": "column"
      },
      {
        "key": "__2__",
        "name": "PromoType",
        "description": "IMS Processed[PromoType]",
        "type": "text",
        "kind": "column"
      },
      {
        "key": "__3__",
        "name": "Channel",
        "description": "All Channel[Channel]",
        "type": "text",
        "kind": "column"
      },
      {
        "key": "__4__",
        "name": "Channel Metric",
        "description": "Value or Volume — switches on Metric Slicer + Source",
        "type": "numeric",
        "kind": "measure"
      },
      {
        "key": "__5__",
        "name": "Channel Metric Share",
        "description": "Value Share or Volume Share decimal",
        "type": "numeric",
        "kind": "measure"
      },
      {
        "key": "__6__",
        "name": "Channel Metric Growth",
        "description": "Growth YoY decimal",
        "type": "numeric",
        "kind": "measure"
      },
      {
        "key": "__7__",
        "name": "Channel Metric Change",
        "description": "Share Change pp decimal",
        "type": "numeric",
        "kind": "measure"
      }
    ]
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": "transparent"
    },
    "font": "Segoe UI, wf_standard-font, helvetica, arial, sans-serif",
    "header": {
      "titleFontSize": 0,
      "labelFontSize": 12,
      "labelFontWeight": "normal",
      "labelColor": "#444444",
      "labelLimit": 200,
      "labelPadding": 4
    },
    "facet": {
      "spacing": {
        "row": 3,
        "column": 3
      }
    }
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "datum[''Parameter Order''] === 0 ? datum[''Brand Strategy''] : datum[''PromoType'']",
      "as": "RowLabel"
    },
    {
      "filter": "(datum[''Parameter Order''] === 0 && datum[''Brand Strategy''] != null) || (datum[''Parameter Order''] === 1 && datum[''PromoType''] != null)"
    },
    {
  "aggregate": [
    { "op": "sum",  "field": "Channel Metric",        "as": "Channel Metric" },
    { "op": "mean", "field": "Channel Metric Share",  "as": "Channel Metric Share" },
    { "op": "mean", "field": "Channel Metric Growth", "as": "Channel Metric Growth" },
    { "op": "mean", "field": "Channel Metric Change", "as": "Channel Metric Change" },
    { "op": "min",  "field": "Parameter Order",       "as": "Parameter Order" }
  ],
  "groupby": ["RowLabel", "Channel"]
},
{
  "filter": "datum[''Parameter Order''] !== null"
},
    {
      "joinaggregate": [
        { "op": "min", "field": "Channel Metric", "as": "row_min" },
        { "op": "max", "field": "Channel Metric", "as": "row_max" }
      ]
    },
    {
      "calculate": "(datum[''row_max''] - datum[''row_min'']) > 0 ? (datum[''Channel Metric''] - datum[''row_min'']) / (datum[''row_max''] - datum[''row_min'']) : 0",
      "as": "norm"
    },
    {
      "calculate": "datum[''Channel Metric''] == null || datum[''Channel Metric''] == 0 ? -1 : datum[''norm''] < 0.1 ? 0 : datum[''norm''] < 0.25 ? 1 : datum[''norm''] < 0.5 ? 2 : datum[''norm''] < 0.75 ? 3 : 4",
      "as": "colorBand"
    },
    {
      "calculate": "datum[''Channel Metric''] != null ? (abs(datum[''Channel Metric'']) >= 1000000 ? format(datum[''Channel Metric'']/1000000, '',.2f'') + ''M'' : abs(datum[''Channel Metric'']) >= 1000 ? format(datum[''Channel Metric'']/1000, '',.2f'') + ''K'' : format(datum[''Channel Metric''], '',.2f'')) : ''''",
      "as": "lbl_value"
    },
    {
      "calculate": "datum[''Channel Metric Share''] != null ? format(datum[''Channel Metric Share''] * 100, ''.0f'') + ''%'' : ''''",
      "as": "lbl_share"
    },
    {
      "calculate": "datum[''Channel Metric Growth''] != null ? (datum[''Channel Metric Growth''] >= 0 ? ''+'' : '''') + format(datum[''Channel Metric Growth''] * 100, ''.0f'') + ''%'' : ''''",
      "as": "lbl_growth"
    },
    {
      "calculate": "datum[''Channel Metric Change''] != null ? (datum[''Channel Metric Change''] >= 0 ? ''+'' : '''') + format(datum[''Channel Metric Change''] * 100, ''.1f'') + ''pp'' : ''''",
      "as": "lbl_change"
    }
  ],
  "facet": {
    "row": {
      "field": "RowLabel",
      "type": "nominal",
      "header": {
        "title": null,
        "labelFontSize": 12,
        "labelFontWeight": "600",
        "labelAlign": "left",
        "labelBaseline": "middle",
        "labelAngle": 0,
        "labelPadding": 8,
        "labelColor": "#252423",
        "labelLimit": 150
      }
    },
    "column": {
      "field": "Channel",
      "type": "nominal",
      "header": {
        "title": null,
        "labelFontSize": 11,
        "labelFontWeight": "600",
        "labelAlign": "center",
        "labelAngle": 0,
        "labelPadding": 4,
        "labelColor": "#252423",
        "labelLimit": 140
      }
    }
  },
  "spec": {
    "width": 180,
    "height": 60,
    "layer": [
      {
        "description": "Background tile — GLOBAL normalised color band -1..4 (Grey = lowest 10% / no data, Navy = highest 10%)",
        "mark": {
          "type": "rect",
          "cornerRadius": 5
        },
        "encoding": {
          "color": {
            "field": "colorBand",
            "type": "ordinal",
            "scale": {
              "domain": [-1, 0, 1, 2, 3, 4],
              "range": [
                "#AEB4B8",
                "#AEB4B8",
                "#48CAE4",
                "#1FA3B5",
                "#0077B6",
                "#0B2E6B"
              ]
            },
            "legend": null
          },
          "tooltip": [
            { "field": "RowLabel",   "title": "Dimension" },
            { "field": "Channel",    "title": "Channel" },
            { "field": "lbl_value",  "title": "Metric" },
            { "field": "lbl_share",  "title": "Share" },
            { "field": "lbl_growth", "title": "Growth YoY" },
            { "field": "lbl_change", "title": "Share Chg (pp)" }
          ]
        }
      },
      {
        "description": "Top-left: Share Change pp",
        "mark": {
          "type": "text",
          "align": "left",
          "baseline": "top",
          "dx": 9,
          "dy": 7,
          "fontSize": 12,
          "fontWeight": "bold",
          "font": "Segoe UI"
        },
        "encoding": {
          "text": { "field": "lbl_change", "type": "nominal" },
          "color": { "condition": { "test": "datum.colorBand <= 1", "value": "#0B2E6B" }, "value": "white" }
        }
      },
      {
        "description": "Top-right: Growth YoY%",
        "mark": {
          "type": "text",
          "align": "right",
          "baseline": "top",
          "dx": -9,
          "dy": 9,
          "fontSize": 12,
          "fontWeight": "bold",
          "font": "Segoe UI"
        },
        "encoding": {
          "text": { "field": "lbl_growth", "type": "nominal" },
          "color": { "condition": { "test": "datum.colorBand <= 1", "value": "#0B2E6B" }, "value": "white" }
        }
      },
      {
        "description": "Bottom-left: Share %",
        "mark": {
          "type": "text",
          "align": "left",
          "baseline": "bottom",
          "dx": 9,
          "dy": -8,
          "fontSize": 12,
          "fontWeight": "bold",
          "font": "Segoe UI"
        },
        "encoding": {
          "text": { "field": "lbl_share", "type": "nominal" },
          "color": { "condition": { "test": "datum.colorBand <= 1", "value": "#0B2E6B" }, "value": "white" }
        }
      },
      {
        "description": "Bottom-right: Metric value",
        "mark": {
          "type": "text",
          "align": "right",
          "baseline": "bottom",
          "dx": -9,
          "dy": -8,
          "fontSize": 12,
          "fontWeight": "bold",
          "font": "Segoe UI"
        },
        "encoding": {
          "text": { "field": "lbl_value", "type": "nominal" },
          "color": { "condition": { "test": "datum.colorBand <= 1", "value": "#0B2E6B" }, "value": "white" }
        }
      }
    ]
  }
}'
